#define main historical_main
#include "../rainflow-cuda/main.cu"
#undef main
#include <vector>
#include <array>
#include <algorithm>
static_assert(sizeof(double3)==24,"nativeCUDA double3 layout must24bytes");
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
std::vector<std::array<double,3>> list_oracle(std::vector<double>&h){std::vector<double>clean;for(double v:h)if(clean.empty()||v!=clean.back())clean.push_back(v);std::vector<double>ext;if(clean.size()==1)ext={clean[0],clean[0]};else{ext.push_back(clean[0]);for(int j=1;j+1<(int)clean.size();j++)if((clean[j]-clean[j-1])*(clean[j+1]-clean[j])<0)ext.push_back(clean[j]);ext.push_back(clean.back());}std::vector<double>stack;std::vector<std::array<double,3>>cycles;for(double v:ext){stack.push_back(v);while(stack.size()>=3&&fabs(stack.back()-stack[stack.size()-2])>=fabs(stack[stack.size()-2]-stack[stack.size()-3])){int m=stack.size();double range=fabs(stack[m-2]-stack[m-3]),mean=.5*(stack[m-2]+stack[m-3]);cycles.push_back({m==3?.5:1.,range,mean});if(m==3)stack.erase(stack.begin());else stack.erase(stack.end()-3,stack.end()-1);}}for(int j=0;j+1<(int)stack.size();j++)cycles.push_back({.5,fabs(stack[j]-stack[j+1]),.5*(stack[j]+stack[j+1])});double sum=0;for(auto c:cycles){if((c[0]!=.5&&c[0]!=1)||c[1]<0)exit(3);sum+=c[0];}if(2*sum!=ext.size()-1)exit(4);return cycles;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;int n=257;std::vector<std::vector<double>>fixed={{0,1},{0,1,0},{0,3,1,2,0},{0,0,1,1,0,0},{2,2,2,2},{-3,-2,0,1,4}};std::vector<double>history;std::vector<int>offsets={0};std::vector<std::vector<std::array<double,3>>>oracle;int valid=0;for(int id=0;id<n;id++){std::vector<double>h;if(id<6)h=fixed[id];else for(int j=0;j<16+(id*13)%113;j++)h.push_back(j>0&&j%7==0?h.back():double((j*17+id*7)%37-18)/8.+double(id%3-1)*j/64.);auto cycles=list_oracle(h);if(id==1&&cycles!=std::vector<std::array<double,3>>{{.5,1,.5},{.5,1,.5}})return 5;if(id==2&&cycles!=std::vector<std::array<double,3>>{{1,1,1.5},{.5,3,1.5},{.5,3,1.5}})return 6;valid+=cycles.size();oracle.push_back(cycles);history.insert(history.end(),h.begin(),h.end());offsets.push_back(history.size());}int L=history.size();std::vector<double3>gold(L),initial(L);for(int j=0;j<L;j++)gold[j]=initial[j]=make_double3(-123.25,-123.25,-123.25);std::vector<int>counts(n);for(int id=0;id<n;id++){counts[id]=oracle[id].size();for(int j=0;j<counts[id];j++){auto v=oracle[id][j];gold[offsets[id]+j]=make_double3(v[0],v[1],v[2]);}}std::vector<double>scratch(L);std::vector<int>pointsCPU(L),refcounts(n);auto ref=initial;reference(history.data(),offsets.data(),scratch.data(),pointsCPU.data(),ref.data(),refcounts.data(),n);if(counts!=refcounts||memcmp(ref.data(),gold.data(),L*24))return 7;double *dh,*de;double3*dr;int*doff,*dp,*dl;CK(cudaMalloc(&dh,L*8));CK(cudaMalloc(&de,L*8));CK(cudaMalloc(&dr,L*24));CK(cudaMalloc(&doff,(n+1)*4));CK(cudaMalloc(&dp,L*4));CK(cudaMalloc(&dl,n*4));CK(cudaMemcpy(dh,history.data(),L*8,cudaMemcpyHostToDevice));CK(cudaMemcpy(doff,offsets.data(),(n+1)*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dr,initial.data(),L*24,cudaMemcpyHostToDevice));CK(cudaMemset(dl,0xff,n*4));rainflow_count<<<2,256>>>(dh,doff,de,dp,dr,dl,n);CK(cudaDeviceSynchronize());std::vector<double>prefix=history;prefix.insert(prefix.end(),offsets.begin(),offsets.end());bool allok=true;for(int trial=1;trial<=5;trial++){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)rainflow_count<<<2,256>>>(dh,doff,de,dp,dr,dl,n);CK(cudaDeviceSynchronize());double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<double3>got(L);std::vector<int>lengths(n);CK(cudaMemcpy(got.data(),dr,L*24,cudaMemcpyDeviceToHost));CK(cudaMemcpy(lengths.data(),dl,n*4,cudaMemcpyDeviceToHost));bool ok=lengths==counts&&memcmp(got.data(),gold.data(),L*24)==0;allok&=ok;auto output=prefix;output.insert(output.end(),lengths.begin(),lengths.end());for(auto c:got){output.push_back(c.x);output.push_back(c.y);output.push_back(c.z);}char file[80];sprintf(file,"rainflow_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),8,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"valid_cycles\":%d,\"computed_output_values\":%d,\"defined_padding_values\":%d,\"input_prefix_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"complete257_variable_length_histories_full_rainflow_counts_ranges_means\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",output.size(),valid,n+3*valid,3*(L-valid),prefix.size(),repeat,file,output.size());}CK(cudaFree(dh));CK(cudaFree(de));CK(cudaFree(dr));CK(cudaFree(doff));CK(cudaFree(dp));CK(cudaFree(dl));puts(allok?"PASS":"FAIL");return allok?0:1;}
